import type { Metadata } from 'next'

export const OG_WIDTH = 1200
export const OG_HEIGHT = 630

export const SITE_NAME = 'Road Map Col'
export const OG_LOCALE = 'en_US'

/** Full-size brand logo (transparent PNG, 1401×999). */
export const LOGO_URL =
  'https://res.cloudinary.com/lesteban/image/upload/v1748229585/roadmap/road_map_sin_fondo_atjeji.png'
export const LOGO_WIDTH = 1401
export const LOGO_HEIGHT = 999
const LOGO_OVERLAY = 'roadmap:road_map_sin_fondo_atjeji'

/**
 * Default share image generated by `src/app/opengraph-image.tsx` (logo
 * centered on white). Referenced explicitly because a page that sets its own
 * `openGraph` does not inherit the root segment's file-based image.
 */
export const DEFAULT_OG_IMAGE = '/opengraph-image'

/**
 * Build a 1200×630 social preview from a Cloudinary image (or video frame).
 * Falls back to the branded logo OG when the source is missing/non-Cloudinary.
 */
export function ogImageUrl(sourceUrl?: string): string {
  if (!sourceUrl?.includes('res.cloudinary.com')) return DEFAULT_OG_IMAGE

  const match = sourceUrl.match(
    /^(https:\/\/res\.cloudinary\.com\/[^/]+)\/(image|video)\/upload\/(?:.*\/)?(v\d+\/.+)$/
  )
  if (!match) return DEFAULT_OG_IMAGE

  const [, host, resourceType, publicIdWithVersion] = match
  const isVideo = resourceType === 'video'
  // so_0 grabs first frame; force jpg for reliable social crawlers
  const transforms = [
    isVideo ? 'so_0' : null,
    `w_${OG_WIDTH}`,
    `h_${OG_HEIGHT}`,
    'c_fill',
    'g_auto',
    'f_jpg',
    'q_auto',
    // brand mark bottom-right
    `l_${LOGO_OVERLAY},w_100,o_90,g_south_east,x_32,y_32`,
  ]
    .filter(Boolean)
    .join(',')

  const id = isVideo
    ? publicIdWithVersion.replace(/\.(mov|mp4|webm)$/i, '.jpg')
    : publicIdWithVersion

  return `${host}/image/upload/${transforms}/${id}`
}

/** Open Graph + Twitter card metadata for any page. */
export function socialMetadata(opts: {
  alt?: string
  description: string
  imageUrl?: string
  title: string
  url?: string
}): Pick<Metadata, 'openGraph' | 'twitter'> {
  const image = ogImageUrl(opts.imageUrl)
  const alt = opts.alt ?? opts.title

  // Next.js replaces (not merges) the parent's openGraph, so repeat the
  // site-wide fields here.
  return {
    openGraph: {
      description: opts.description,
      images: [
        {
          alt,
          height: OG_HEIGHT,
          url: image,
          width: OG_WIDTH,
        },
      ],
      locale: OG_LOCALE,
      siteName: SITE_NAME,
      title: opts.title,
      type: 'website',
      ...(opts.url ? { url: opts.url } : {}),
    },
    twitter: {
      card: 'summary_large_image',
      description: opts.description,
      images: [image],
      title: opts.title,
    },
  }
}
